CREATE TABLE IF NOT EXISTS rma_requests (ref TEXT PRIMARY KEY, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'New', assigned TEXT, notes TEXT, contact TEXT, company TEXT, phone TEXT, email TEXT, cc TEXT, type TEXT, urgent TEXT, flag_receipt TEXT, verified TEXT, hot TEXT, auto_return TEXT, company_address TEXT, shipping_address TEXT, units TEXT, email_status TEXT, updated TEXT, updated_by TEXT);
